const Perk=require("../models/perksModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_perk=(r,t,e)=>{Perk.create(r.body).then(e=>{t.status(200).send(e)}).catch(e=>{t.status(422).send(handleErrors(e,r,"perk"))})},get_perks=(e,r,t)=>{Perk.find({}).then(e=>{r.status(200).send({perks:e})}).catch(t)},get_admin_perks=(e,t,s)=>{const d=e.query.page-1||0;Perk.find({}).count().then(r=>{Perk.find({}).skip(30*d).limit(30).then(e=>t.status(200).send({perks:e,total_perks:r,per_page:30})).catch(s)})},get_single_perk=(e,r,t)=>{Perk.findById({_id:e.params.id}).then(e=>r.status(200).send(e)).catch(t)},update_perk=(r,t,e)=>{Perk.findByIdAndUpdate({_id:r.params.id},r.body).then(e=>{Perk.findOne({_id:r.params.id}).then(e=>t.status(200).send(e))}).catch(e)},delete_perk=(e,r,t)=>{Perk.findByIdAndDelete({_id:e.params.id}).then(e=>{r.status(200).send(e)}).catch(t)};module.exports={create_perk:create_perk,update_perk:update_perk,get_single_perk:get_single_perk,get_admin_perks:get_admin_perks,get_perks:get_perks,delete_perk:delete_perk};